def transform(grid):
    """Restore large rectangular panels, removing scattered corrupted cells."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]

    # Identify substantial non-background row runs, merge those vertically
    # overlapping into region proposals, then tighten each proposal to a box.
    for color in set(v for row in grid for v in row if v != bg):
        runs=[]
        for r,row in enumerate(grid):
            c=0
            while c<len(row):
                if row[c]!=color:
                    c+=1; continue
                a=c
                while c<len(row) and row[c]==color: c+=1
                if c-a>=2: runs.append((r,a,c))
        parent=list(range(len(runs)))
        def root(i):
            while parent[i]!=i:
                parent[i]=parent[parent[i]]
                i=parent[i]
            return i
        for i,(r,a,b) in enumerate(runs):
            for j,(rr,x,y) in enumerate(runs[:i]):
                # Adjacent rows of the same rectangle have strongly aligned spans.
                overlap=max(0,min(b,y)-max(a,x))
                if abs(r-rr)<=2 and overlap>=min(2,b-a,y-x):
                    ri,rj=root(i),root(j)
                    if ri!=rj: parent[ri]=rj
        groups={}
        for i,run in enumerate(runs): groups.setdefault(root(i),[]).append(run)
        for g in groups.values():
            rs=sorted(set(x[0] for x in g))
            if len(rs)<2: continue
            # Split a cluster at large vertical gaps.
            chunks=[]
            for rr in rs:
                if not chunks or rr>chunks[-1][-1]+2: chunks.append([rr])
                else: chunks[-1].append(rr)
            for chunk in chunks:
                gg=[x for x in g if x[0] in chunk]
                r0,r1=min(chunk),max(chunk)
                c0=min(x[1] for x in gg); c1=max(x[2] for x in gg)
                area=(r1-r0+1)*(c1-c0)
                observed=sum(grid[r][c]==color for r in range(r0,r1+1) for c in range(c0,min(c1,len(grid[r]))))
                if area>=6 and observed/area>=0.65:
                    for r in range(r0,r1+1):
                        for c in range(c0,c1):
                            if c<w: out[r][c]=color
    return out
