def transform(grid):
    """Restore large, mostly uniform rectangles and remove isolated noise."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    colors = set(v for row in grid for v in row if v != bg)
    proposals = []

    # Enumerate dense same-color rectangles, allowing occasional corrupted cells.
    for color in colors:
        for r0 in range(h):
            for r1 in range(r0 + 2, h + 1):
                for c0 in range(w):
                    for c1 in range(c0 + 2, w + 1):
                        if any(c1 > len(grid[r]) for r in range(r0, r1)):
                            continue
                        area = (r1-r0) * (c1-c0)
                        n = sum(grid[r][c] == color
                                for r in range(r0, r1) for c in range(c0, c1))
                        if n < 6 or n / area < 0.78:
                            continue
                        row_support = sum(sum(grid[r][c] == color for c in range(c0, c1)) >= 2
                                          for r in range(r0, r1))
                        col_support = sum(sum(grid[r][c] == color for r in range(r0, r1)) >= 2
                                          for c in range(c0, c1))
                        if row_support < max(2, (r1-r0)-1) or col_support < max(2, (c1-c0)-1):
                            continue
                        proposals.append((n/area, n, area, r0, r1, c0, c1, color))

    # Set cover prioritizes rectangles explaining many still-unexplained pixels.
    remaining = {(r,c) for r in range(h) for c in range(len(grid[r])) if grid[r][c] != bg}
    while remaining:
        best = None
        best_score = 0
        for item in proposals:
            density, n, area, r0, r1, c0, c1, color = item
            hits = sum((r,c) in remaining and grid[r][c] == color
                       for r in range(r0,r1) for c in range(c0,c1))
            score = hits - 0.12*(area-hits)
            if hits >= 6 and score > best_score:
                best, best_score = item, score
        if best is None:
            break
        _,_,_,r0,r1,c0,c1,color = best
        for r in range(r0,r1):
            for c in range(c0,c1):
                out[r][c] = color
        remaining -= {(r,c) for r in range(r0,r1) for c in range(c0,c1)
                      if grid[r][c] == color}
        proposals.remove(best)
